parameters.functionCode:
const leads = $input.all();
const now = new Date();
const followUpLeads = [];

leads.forEach(lead => {
  const leadData = lead.json;
  const documentRequestDate = new Date(leadData.customFields.documentRequestedAt || leadData.updatedAt);
  const daysSinceRequest = Math.floor((now - documentRequestDate) / (1000 * 60 * 60 * 24));

  // Different follow-up schedules based on lead grade
  const leadGrade = leadData.customFields.nyraLeadGrade || 'C';
  let shouldFollowUp = false;
  let followUpType = '';

  if (leadGrade === 'A') {
    // Grade A: Follow up after 1, 2, and 3 days
    if (daysSinceRequest === 1 || daysSinceRequest === 2 || daysSinceRequest === 3) {
      shouldFollowUp = true;
      followUpType = daysSinceRequest === 3 ? 'final' : 'reminder';
    }
  } else if (leadGrade === 'B') {
    // Grade B: Follow up after 2 and 5 days
    if (daysSinceRequest === 2 || daysSinceRequest === 5) {
      shouldFollowUp = true;
      followUpType = daysSinceRequest === 5 ? 'final' : 'reminder';
    }
  } else {
    // Grade C/D: Follow up after 3 and 7 days
    if (daysSinceRequest === 3 || daysSinceRequest === 7) {
      shouldFollowUp = true;
      followUpType = daysSinceRequest === 7 ? 'final' : 'reminder';
    }
  }

  if (shouldFollowUp) {
    followUpLeads.push({
      ...leadData,
      followUpDetails: {
        daysSinceRequest,
        followUpType,
        leadGrade
      }
    });
  }
});

return followUpLeads.map(lead => ({ json: lead }));

